class ModelTemplateDragon extends ModelCreatureObj {
  foldWings = true;
  animatePart(partName, entity, time, distance, loop, lookY, lookX, scale) {
      super.animatePart(partName, entity, time, distance, loop, lookY, lookX, scale);
      let posX = 0.0;
      let posY = 0.0;
      let posZ = 0.0;
      let angleX = 0.0;
      let angleY = 0.0;
      let angleZ = 0.0;
      let rotation = 0.0;
      let rotX = 0.0;
      let rotY = 0.0;
      let rotZ = 0.0;
      if((partName === "mouth") || (partName === "mouthbottom")) {
         this.rotate((-toDeg((mcCos(loop * 0.1) * 0.1 - 0.1))), 0.0, 0.0);
      }

      if((partName === "mouthtop")) {
         this.rotate(toDeg((mcCos(loop * 0.1) * 0.1 - 0.1)), 0.0, 0.0);
      }

      if((partName === "neck")) {
         this.rotate((-toDeg((mcCos(loop * 0.09) * 0.05 - 0.05))), 0.0, 0.0);
      }

      if((partName === "tail") || (partName === "tail01") || (partName === "tail02")) {
         rotX += (-toDeg((mcCos(loop * 0.1) * 0.05 - 0.25)));
         rotY += (-toDeg((mcCos(loop * 0.05) * 0.05)));
      }

      let flightLoop ;
      let flightLoopRev ;
      if(entity != null && entity.onGround) {
         flightLoop = mcCos(time * 0.3);
         flightLoopRev = mcCos(time * 0.3 + 3.1415927);
         let walkIdle = mcSin(loop * 0.1);
         let walkIdleRev = mcSin(loop * 0.1 + 3.1415927);
         let walkSwing = 0.6;
         if((partName === "legleft") || (partName === "legrightfront") || (partName === "armrightfront01") || (partName === "legleftback")) {
            rotX = (rotX + toDeg((flightLoopRev * walkSwing * distance)));
         }

         if((partName === "legright") || (partName === "legleftfront") || (partName === "armleftfront01") || (partName === "legrightback")) {
            rotX = (rotX + toDeg((flightLoop * walkSwing * distance)));
         }

         if((partName === "armleft01")) {
            rotX = (rotX + toDeg((flightLoop * (walkSwing / 2.0) * distance)));
            rotY -= 10.0;
            rotZ -= 25.0;
         }

         if((partName === "armright01")) {
            rotX = (rotX + toDeg((flightLoopRev * (walkSwing / 2.0) * distance)));
            rotY += 10.0;
            rotZ += 25.0;
         }

         if(this.foldWings) {
            if((partName === "wingleft01")) {
               rotX = (rotX + toDeg((walkIdle * 0.1)));
               rotZ = (rotZ - toDeg((walkIdle * 0.1)));
               rotZ += 80.0;
            }

            if((partName === "wingright01")) {
               rotX = (rotX + toDeg((walkIdle * 0.1)));
               rotZ = (rotZ - toDeg((walkIdleRev * 0.1)));
               rotZ -= 80.0;
            }

            if((partName === "wingleft02")) {
               rotZ = (rotZ + toDeg((walkIdle * 0.1)));
               rotZ -= 170.0;
               rotX -= 10.0;
            }

            if((partName === "wingright02")) {
               rotZ = (rotZ - toDeg((walkIdle * 0.1)));
               rotZ += 170.0;
               rotX -= 10.0;
            }

            if((partName === "wingleftupper")) {
               rotX = (rotX + 20.0 + toDeg((walkIdle * 0.1)));
               rotY += 60.0;
               rotZ = (rotZ - toDeg((walkIdle * 0.1)));
            }

            if((partName === "wingrightupper")) {
               rotX = (rotX + 20.0 + toDeg((walkIdle * 0.1)));
               rotY -= 60.0;
               rotZ = (rotZ - toDeg((walkIdleRev * 0.1)));
            }

            if((partName === "wingleftlower")) {
               rotZ = (rotZ + (toDeg((walkIdle * 0.1 - 0.1)) - 35.0));
            }

            if((partName === "wingrightlower")) {
               rotZ = (rotZ - (toDeg((walkIdle * 0.1 - 0.1)) - 35.0));
            }
         }
      }

      if(entity != null && !entity.onGround) {
         flightLoop = mcSin(loop * 0.4);
         flightLoopRev = mcSin(loop * 0.4 + 3.1415927);
         if((partName === "body") && entity.getPassengers().isEmpty()) {
            posY += flightLoop / 2.0;
         }

         if((partName === "head")) {
            rotX = (rotX - toDeg((flightLoop * 0.05)));
         }

         if((partName === "legleftfront") || (partName === "legrightfront")) {
            rotX += 25.0;
            rotX = (rotX + toDeg((flightLoop * 0.1)));
         }

         if((partName === "legleftback") || (partName === "legrightback")) {
            rotX += 25.0;
            rotX = (rotX - toDeg((flightLoop * 0.1)));
         }

         if(this.foldWings) {
            if((partName === "wingleft")) {
               rotX = (rotX - toDeg((flightLoop * 0.6)));
               rotZ = (rotZ - toDeg((flightLoop * 0.6)));
            }

            if((partName === "wingright")) {
               rotX = (rotX - toDeg((flightLoop * 0.6)));
               rotZ = (rotZ - toDeg((flightLoopRev * 0.6)));
            }

            if((partName === "wingleft01") || (partName === "armleft01") || (partName === "wingleftupper")) {
               rotX = (rotX - toDeg((flightLoop * 0.3)));
               rotZ = (rotZ - toDeg((flightLoop * 0.3)));
            }

            if((partName === "wingright01") || (partName === "armright01") || (partName === "wingrightupper")) {
               rotX = (rotX - toDeg((flightLoop * 0.3)));
               rotZ = (rotZ - toDeg((flightLoopRev * 0.3)));
            }

            if((partName === "wingleft02") || (partName === "armleft02")) {
               rotZ = (rotZ - toDeg((flightLoop * 0.3)));
            }

            if((partName === "wingright02") || (partName === "armright02")) {
               rotZ = (rotZ - toDeg((flightLoopRev * 0.3)));
            }
         }
      }

      if(!(partName === "mouth") && !(partName === "mouthbottom")) {
         if((partName === "mouthtop")) {
            rotX += 15.0 * this.getAttackProgress();
         }
      } else {
         rotX -= 15.0 * this.getAttackProgress();
      }

      this.angle(rotation, angleX, angleY, angleZ);
      this.rotate(rotX, rotY, rotZ);
      this.translate(posX, posY, posZ);
  }
}
